module tb_TopModule;
  logic clk;
  logic reset;
  logic w;
  logic z;

  TopModule uut (
    .clk(clk),
    .reset(reset),
    .w(w),
    .z(z)
  );

  always #5 clk = ~clk;

  initial begin
    clk = 0;
    reset = 1;
    w = 0;
    #12;
    reset = 0;

    // Test sequence starting at A (reset state, z=0)
    // A -> (w=0) -> B (z=0)
    w = 0;
    @(posedge clk);
    #1;
    if (z !== 0) begin $display("SELFTEST FAIL: at B, z expected 0, got %b", z); $finish; end

    // B -> (w=1) -> D (z=0)
    w = 1;
    @(posedge clk);
    #1;
    if (z !== 0) begin $display("SELFTEST FAIL: at D, z expected 0, got %b", z); $finish; end

    // D -> (w=0) -> F (z=1)
    w = 0;
    @(posedge clk);
    #1;
    if (z !== 1) begin $display("SELFTEST FAIL: at F, z expected 1, got %b", z); $finish; end

    // F -> (w=0) -> C (z=0)
    w = 0;
    @(posedge clk);
    #1;
    if (z !== 0) begin $display("SELFTEST FAIL: at C, z expected 0, got %b", z); $finish; end

    // C -> (w=0) -> E (z=1)
    w = 0;
    @(posedge clk);
    #1;
    if (z !== 1) begin $display("SELFTEST FAIL: at E, z expected 1, got %b", z); $finish; end

    // E -> (w=0) -> E (z=1)
    w = 0;
    @(posedge clk);
    #1;
    if (z !== 1) begin $display("SELFTEST FAIL: at E (stay), z expected 1, got %b", z); $finish; end

    // E -> (w=1) -> D (z=0)
    w = 1;
    @(posedge clk);
    #1;
    if (z !== 0) begin $display("SELFTEST FAIL: at D, z expected 0, got %b", z); $finish; end

    // D -> (w=1) -> A (z=0)
    w = 1;
    @(posedge clk);
    #1;
    if (z !== 0) begin $display("SELFTEST FAIL: at A, z expected 0, got %b", z); $finish; end

    // Test reset during operation
    w = 0; // A -> B
    @(posedge clk);
    #1;
    reset = 1;
    @(posedge clk);
    #1;
    reset = 0;
    if (z !== 0) begin $display("SELFTEST FAIL: reset failed"); $finish; end
    // Should be at A now. w=0 -> B
    @(posedge clk);
    #1;
    // B -> w=1 -> D
    w = 1;
    @(posedge clk);
    #1;
    if (z !== 0) begin $display("SELFTEST FAIL: reset sequence check"); $finish; end

    $display("SELFTEST PASS");
    $finish;
  end
endmodule
